12	/// Tela 0.1a (prototype-extract.md §4): "Entrar"/"Criar conta", two
13	/// `AppTextField`s + one `AppButton` + a ghost toggle link — unchanged
14	/// shared primitives, no new params. No "usar biometria" link (Epic 2's
15	/// vault isn't built — omitted rather than shipped dead); no
16	/// `SessionStatus`/`go_router` (Story 1.4/1.6 scope): [onAuthenticated] is
17	/// how the caller (`main.dart`) decides what comes after success.
18	class AuthScreen extends StatelessWidget {
19	  const AuthScreen({
20	    super.key,
21	    required this.cubit,
22	    required this.onAuthenticated,
23	  });
24	
25	  final AuthCubit cubit;
26	
27	  /// Called once, the first time `state.status` becomes `ResourceData`
28	  /// (i.e. the access token has already been persisted — the repository
29	  /// saves it before resolving).
30	  final void Function(BuildContext context) onAuthenticated;
31	
32	  @override
33	  Widget build(BuildContext context) {
34	    return BlocProvider.value(
35	      value: cubit,
36	      child: BlocListener<AuthCubit, AuthState>(
37	        listenWhen: (previous, current) =>
38	            current.status is ResourceData<Unit> &&
39	            previous.status is! ResourceData<Unit>,
40	        listener: (context, state) => onAuthenticated(context),
41	        child: const _AuthView(),
42	      ),
43	    );
44	  }
45	}
46	
47	class _AuthView extends StatefulWidget {
48	  const _AuthView();
49	
50	  @override
51	  State<_AuthView> createState() => _AuthViewState();
52	}
53	
54	class _AuthViewState extends State<_AuthView> {
55	  final _emailController = TextEditingController();
56	  final _passwordController = TextEditingController();
57	  final _passwordFocus = FocusNode();
58	
59	  @override
60	  void dispose() {
61	    _emailController.dispose();
62	    _passwordController.dispose();
63	    _passwordFocus.dispose();
64	    super.dispose();
65	  }
66	
67	  // Keeps the (locally-owned) text controllers in sync with the cubit's
68	  // state without fighting the user's caret position — only written when
69	  // the value actually diverges (e.g. on `toggleMode`, which doesn't touch
70	  // field values, this is a no-op). On `AUTH_INVALID`/network failure the
71	  // cubit state's `email`/`password` are untouched, so this keeps the
72	  // user's typed values exactly as they were (epics.md Story 1.3 AC).
73	  void _syncControllers(AuthState state) {
74	    if (_emailController.text != state.email) {
75	      _emailController.value = _emailController.value.copyWith(
76	        text: state.email,
77	        selection: TextSelection.collapsed(offset: state.email.length),
78	      );
79	    }
80	    if (_passwordController.text != state.password) {
81	      _passwordController.value = _passwordController.value.copyWith(
82	        text: state.password,
83	        selection: TextSelection.collapsed(offset: state.password.length),
84	      );
85	    }
86	  }
87	
88	  @override
89	  Widget build(BuildContext context) {
90	    return Scaffold(
91	      backgroundColor: DesignTokens.colorSurfaceBg,
92	      body: SafeArea(
93	        child: BlocBuilder<AuthCubit, AuthState>(
94	          builder: (context, state) {
95	            _syncControllers(state);
96	
97	            final cubit = context.read<AuthCubit>();
98	            final isLogin = state.mode == AuthMode.login;
99	            final isSubmitting = state.isSubmitting;
100	
101	            // Both fields get the error border on a form-level failure
102	            // (AUTH_INVALID/network); the message itself is shown once,
103	            // under senha. `errorText: ''` on e-mail is border-only
104	            // (app_text_field.dart's documented convention). A local,
105	            // password-only validation error (`passwordError`, "Senha
106	            // obrigatória") is single-field — the e-mail value already
107	            // passed its own check, so it must never be bordered for it.
108	            final emailErrorText = state.emailError ??
109	                (state.formError != null ? '' : null);
110	            final passwordErrorText = state.formError ?? state.passwordError;
111	
112	            return SingleChildScrollView(
113	              padding: DesignTokens.screenPadding,
114	              child: Column(
115	                crossAxisAlignment: CrossAxisAlignment.stretch,
116	                mainAxisSize: MainAxisSize.min,
117	                children: [
118	                  const SizedBox(height: DesignTokens.spacing2xl),
119	                  Text(
120	                    isLogin ? 'Bem-vindo de volta' : 'Crie sua conta',
121	                    textAlign: TextAlign.center,
122	                    style: DesignTokens.textHeadlineMd.copyWith(
123	                      color: DesignTokens.colorTextPrimary,
124	                    ),
125	                  ),
126	                  const SizedBox(height: DesignTokens.spacingLg),
127	                  AppTextField(
128	                    controller: _emailController,
129	                    labelText: 'E-mail',
130	                    keyboardType: TextInputType.emailAddress,
131	                    textInputAction: TextInputAction.next,
132	                    errorText: emailErrorText,
133	                    onChanged: cubit.emailChanged,
134	                  ),
135	                  const SizedBox(height: DesignTokens.spacingMd),
136	                  AppTextField(
137	                    controller: _passwordController,
138	                    focusNode: _passwordFocus,
139	                    labelText: 'Senha',
140	                    obscureText: true,
141	                    textInputAction: TextInputAction.done,
142	                    errorText: passwordErrorText,
143	                    onChanged: cubit.passwordChanged,
144	                  ),
145	                  const SizedBox(height: DesignTokens.spacingLg),
146	                  AppButton(
147	                    label: isSubmitting
148	                        ? (isLogin ? 'Entrando…' : 'Criando conta…')
149	                        : (isLogin ? 'Entrar' : 'Criar conta'),
150	                    onPressed: isSubmitting ? null : cubit.submit,
151	                  ),
152	                  const SizedBox(height: DesignTokens.spacingMd),
153	                  AppButton(
154	                    variant: AppButtonVariant.textGhost,
155	                    label: isLogin
156	                        ? 'Não tem conta? Criar conta'
157	                        : 'Já tem conta? Entrar',
158	                    onPressed: isSubmitting ? null : cubit.toggleMode,
159	                  ),
160	                ],
161	              ),
162	            );
163	          },
164	        ),
165	      ),
166	    );
167	  }
168	}
