35	  setUp(() {
36	    mockRemoteDataSource = MockAuthRemoteDataSource();
37	    mockAccessTokenProvider = MockAccessTokenProvider();
38	    mockSessionExpiryNotifier = MockSessionExpiryNotifier();
39	    expiryController = StreamController<void>.broadcast();
40	    when(() => mockSessionExpiryNotifier.expiredEvents)
41	        .thenAnswer((_) => expiryController.stream);
42	    when(
43	      () => mockAccessTokenProvider.saveSession(
44	        accessToken: any(named: 'accessToken'),
45	        refreshToken: any(named: 'refreshToken'),
