60	  /// Subscribes before [restoreSession] runs (required for a broadcast
61	  /// stream) and drains the microtask queue afterwards so the event posted
62	  /// by `_statusController.add(...)` has definitely been delivered by the
63	  /// time this returns — same rationale as `auth_cubit_test.dart`'s
64	  /// `_emittedDuring` helper.
65	  Future<List<SessionStatus>> emittedDuring(Future<void> Function() act) async {
66	    final emitted = <SessionStatus>[];
67	    final subscription = repository.statusStream.listen(emitted.add);
68	    await act();
69	    await Future<void>.delayed(Duration.zero);
70	    await subscription.cancel();
71	    return emitted;
72	  }
