79	      when(() => mockRemoteDataSource.refresh('stored-refresh-token'))
80	          .thenAnswer((_) async => right(_newSession));
81	
82	      Either<Failure, Unit>? result;
83	      final emitted = await emittedDuring(() async {
84	        result = await repository.restoreSession();
85	      });
86	
87	      expect(emitted, [SessionStatus.authenticated]);
88	      expect(result!.isRight(), isTrue);
89	      verify(
90	        () => mockAccessTokenProvider.saveSession(
