174	
175	    test('backend returns AUTH_INVALID -> session cleared, stream emits '
176	        'unauthenticated', () async {
177	      when(() => mockAccessTokenProvider.readRefreshToken())
178	          .thenAnswer((_) async => 'invalid-refresh-token');
179	      when(
180	        () => mockRemoteDataSource.refresh('invalid-refresh-token'),
181	      ).thenAnswer(
182	        (_) async =>
183	            left(const Failure.authInvalid(message: 'Refresh token invalid')),
