1	import 'dart:async';
2	
3	import 'package:flutter/widgets.dart';
4	import 'package:go_router/go_router.dart';
5	
6	import '../di/injection_container.dart';
7	import '../../features/auth/domain/entities/session_status.dart';
8	import '../../features/auth/domain/repositories/session_repository.dart';
9	import '../../features/auth/presentation/cubit/auth_cubit.dart';
10	import '../../features/auth/presentation/screens/auth_screen.dart';
11	import 'placeholder_screens.dart';
12	
13	/// Every route this story's app shell resolves (Boundaries: "Routes:
14	/// `/boot`, `/auth`, `/reauth`, `/`, `/meus-registros`, `/planos-de-acao`,
15	/// `/configuracoes`"). Named constants so no call site retypes a path
16	/// literal that could drift from the one `GoRouter` below.
17	abstract final class AppRoutePaths {
18	  static const boot = '/boot';
19	  static const auth = '/auth';
20	  static const reauth = '/reauth';
21	  static const home = '/';
22	  static const meusRegistros = '/meus-registros';
23	  static const planosDeAcao = '/planos-de-acao';
24	  static const configuracoes = '/configuracoes';
25	}
26	
27	/// The epic's ONE `GoRouter`/`redirect` (Boundaries: "never a second
28	/// competing `redirect`") — composes only [SessionRepository.currentStatus]
29	/// for now. [sessionRepository] is taken as a parameter (rather than this
30	/// file reaching into `sl` itself) purely so a test can pass a fake/mock one
31	/// directly, without touching the global DI container.
32	GoRouter buildAppRouter({required SessionRepository sessionRepository}) {
33	  return GoRouter(
34	    initialLocation: AppRoutePaths.boot,
35	    refreshListenable: _GoRouterRefreshStream(sessionRepository.statusStream),
36	    redirect: (context, state) => _redirect(sessionRepository, state),
37	    routes: [
38	      GoRoute(
39	        path: AppRoutePaths.boot,
40	        builder: (context, state) => const BootSplashScreen(),
41	      ),
42	      GoRoute(
43	        path: AppRoutePaths.auth,
44	        builder: (context, state) => AuthScreen(
45	          cubit: sl<AuthCubit>(),
46	          onAuthenticated: (context) => context.go(AppRoutePaths.home),
47	        ),
48	      ),
49	      GoRoute(
50	        path: AppRoutePaths.reauth,
51	        builder: (context, state) => const BiometricReauthPlaceholderScreen(),
52	      ),
53	      GoRoute(
54	        path: AppRoutePaths.home,
55	        builder: (context, state) => const HomeChatPlaceholderScreen(),
56	      ),
57	      GoRoute(
58	        path: AppRoutePaths.meusRegistros,
59	        builder: (context, state) => const MeusRegistrosPlaceholderScreen(),
60	      ),
61	      GoRoute(
62	        path: AppRoutePaths.planosDeAcao,
63	        builder: (context, state) => const ActionPlansPlaceholderScreen(),
64	      ),
65	      GoRoute(
66	        path: AppRoutePaths.configuracoes,
67	        builder: (context, state) => const ConfiguracoesPlaceholderScreen(),
68	      ),
69	    ],
70	  );
71	}
72	
73	/// I/O & Edge-Case Matrix:
74	/// - status not yet known (`null`) -> `/boot`, unless already there.
75	/// - `unauthenticated` -> `/auth`, unless already there.
76	/// - `authenticated`/`expired` -> leaves `/boot`/`/auth` for `/`; every
77	///   other location (including `/reauth`, reached only by the expiry
78	///   overlay's own explicit navigation) is left alone — a mid-session
79	///   expiry never navigates away (Story 1.5 behavior preserved), and the
80	///   three non-Home destinations stay reachable while `expired`.
81	///
82	/// AD-14 seam: Epic 2 (RF03) plugs a local `VaultStatus` gate in here,
83	/// checked *before* this session check (Cross-Story Dependencies: "vault
84	/// checked first") — e.g. `if (vaultStatus == VaultStatus.locked) return
85	/// AppRoutePaths.vaultLock;` ahead of the block below. Nothing here should
86	/// assume session validity alone ever decides access once that lands.
87	String? _redirect(SessionRepository sessionRepository, GoRouterState state) {
88	  final status = sessionRepository.currentStatus;
89	  final location = state.matchedLocation;
90	
91	  if (status == null) {
92	    return location == AppRoutePaths.boot ? null : AppRoutePaths.boot;
93	  }
94	
95	  if (status == SessionStatus.unauthenticated) {
96	    return location == AppRoutePaths.auth ? null : AppRoutePaths.auth;
97	  }
98	
99	  // status is authenticated or expired.
100	  if (location == AppRoutePaths.boot || location == AppRoutePaths.auth) {
101	    return AppRoutePaths.home;
102	  }
103	  return null;
104	}
105	
106	/// Wraps [stream] as a `Listenable` so `GoRouter`'s `refreshListenable` can
107	/// re-run [_redirect] on every emission — go_router 18.1.1 exports no
108	/// `GoRouterRefreshStream` of its own (Code Map), so this is that small
109	/// local class.
110	class _GoRouterRefreshStream extends ChangeNotifier {
111	  _GoRouterRefreshStream(Stream<dynamic> stream) {
112	    _subscription = stream.listen((_) => notifyListeners());
113	  }
114	
115	  late final StreamSubscription<dynamic> _subscription;
116	
117	  @override
118	  void dispose() {
119	    _subscription.cancel();
120	    super.dispose();
121	  }
122	}
