1	import 'dart:async';
2	
3	import 'package:flutter/material.dart';
4	import 'package:go_router/go_router.dart';
5	
6	import '../../features/auth/domain/entities/session_status.dart';
7	import '../../features/auth/domain/repositories/session_repository.dart';
8	import '../design_tokens.dart';
9	import '../widgets/confirmation_dialog.dart';
10	import 'app_router.dart';
11	
12	/// `MaterialApp.router`'s `builder:` (moved from `main.dart`, Story 1.5's
13	/// overlay wiring now reworked for `go_router`, Code Map). Wraps whatever
14	/// [child] the router currently shows with the same one-shot
15	/// expired-session overlay `main.dart` used to own directly — the only
16	/// change is that "Entrar novamente" now navigates via [router] instead of
17	/// an imperative `Navigator.push`.
18	///
19	/// [router] is called directly (`router.go(...)`), never via
20	/// `context.go(...)` — `MaterialApp.router`'s `builder:` widget is inserted
21	/// *above* the `Navigator`/`InheritedGoRouter` it wraps (per
22	/// `WidgetsApp.builder`'s own doc), so this widget's own `BuildContext`
23	/// has no `GoRouter` ancestor to look up.
24	///
25	/// Story 1.5's boundaries are unchanged here: the overlay traps focus
26	/// until dismissed/actioned, is the only overlay allowed on screen at a
27	/// time, never navigates away on its own, and fires at most once per
28	/// `expired` episode.
29	class ExpiryOverlayHost extends StatefulWidget {
30	  const ExpiryOverlayHost({
31	    super.key,
32	    required this.sessionRepository,
33	    required this.router,
34	    required this.child,
35	  });
36	
37	  final SessionRepository sessionRepository;
38	  final GoRouter router;
39	  final Widget child;
40	
41	  @override
42	  State<ExpiryOverlayHost> createState() => _ExpiryOverlayHostState();
43	}
44	
45	class _ExpiryOverlayHostState extends State<ExpiryOverlayHost> {
46	  StreamSubscription<SessionStatus>? _subscription;
47	
48	  // Same two one-shot guards `main.dart` used to own (code review of
49	  // story-1-5): `_expiryOverlayShown` is a per-episode latch (nothing
50	  // today transitions `SessionStatus` back out of `expired`, so without
51	  // it a later event on this same subscription would reopen the overlay
52	  // on top of wherever the user already navigated after confirming it);
53	  // `_reauthRouteRequested` guards the dialog's own confirm callback
54	  // against a rapid double-tap during its 180ms exit fade.
55	  bool _expiryOverlayShown = false;
56	  bool _reauthRouteRequested = false;
57	
58	  @override
59	  void initState() {
60	    super.initState();
61	    _subscription = widget.sessionRepository.statusStream.listen(
62	      _onStatus,
63	      // Mirrors `SessionRepositoryImpl`'s own internal subscriptions — no
64	      // current implementation ever errors on this stream, but a future
65	      // one that did must not surface as an unhandled zone exception.
66	      onError: (_, _) {},
67	    );
68	  }
69	
70	  @override
71	  void dispose() {
72	    unawaited(_subscription?.cancel());
73	    super.dispose();
74	  }
75	
76	  void _onStatus(SessionStatus status) {
77	    if (status != SessionStatus.expired || _expiryOverlayShown) {
78	      return;
79	    }
80	    _expiryOverlayShown = true;
81	    // `showGeneralDialog` (inside `ConfirmationDialog.show`) pushes a
82	    // route, which must never happen mid-build/mid-stream-callback —
83	    // deferred to `addPostFrameCallback`, same as `main.dart` did.
84	    WidgetsBinding.instance.addPostFrameCallback((_) {
85	      if (!mounted) {
86	        return;
87	      }
88	      // This widget's own `context` sits *above* the router's `Navigator`
