28	/// Root widget. Portrait-only, light-mode-only, fixed 390x844 frame — no
29	/// breakpoint, landscape or dark-mode path anywhere in the app (per the
30	/// epic's UX constraints; the portrait lock itself lives in
31	/// `ios/Runner/Info.plist`, Story 1.6).
32	///
33	/// Story 1.6 scope: the ad-hoc `StreamBuilder`/`Navigator.push` shell
34	/// Stories 1.3-1.5 built this on top of is replaced by the one real
35	/// `go_router` (`core/navigation/app_router.dart`) plus its
36	/// `ExpiryOverlayHost` wrapper — [restoreSession] still fires once at boot
37	/// here (unchanged from Story 1.4), but every screen transition and the
38	/// expiry overlay's own "Entrar novamente" now go through that router
39	/// instead of an imperative `Navigator`.
40	class CerneApp extends StatefulWidget {
41	  const CerneApp({super.key});
42	
43	  @override
44	  State<CerneApp> createState() => _CerneAppState();
45	}
46	
47	class _CerneAppState extends State<CerneApp> {
48	  late final SessionRepository _sessionRepository;
49	  late final GoRouter _router;
50	
51	  @override
52	  void initState() {
53	    super.initState();
54	    _sessionRepository = sl<SessionRepository>();
55	    _router = buildAppRouter(sessionRepository: _sessionRepository);
56	    // Fire-and-forget: the outcome reaches the UI through
57	    // `SessionRepository.currentStatus`/`statusStream` (which the router's
58	    // `redirect`/`refreshListenable` already watch), not through this
59	    // call's return value. `restoreSession()` already maps every internal
60	    // failure to `Left`/an `unauthenticated` emission and never throws.
61	    // This `catchError` is NOT a UI recovery path — its handler's return
62	    // value is discarded by `unawaited` and never reaches `statusStream`.
63	    // It exists purely so a future regression that broke the "never
64	    // throws" contract above would surface as a logged message instead of
65	    // an unhandled zone exception.
66	    unawaited(
67	      _sessionRepository.restoreSession().catchError(_asUnauthenticated),
68	    );
69	  }
70	
71	  @override
72	  void dispose() {
73	    _router.dispose();
74	    super.dispose();
75	  }
76	
77	  // `catchError`'s handler must still complete the Future with a value of
78	  // its declared type (`Either<Failure, Unit>`) — a `void`-returning
79	  // handler would try to complete it with `null`, which isn't assignable
80	  // to that non-nullable type and would itself throw.
81	  static Either<Failure, Unit> _asUnauthenticated(
82	    Object error,
83	    StackTrace stackTrace,
84	  ) {
85	    debugPrint('CerneApp: restoreSession() threw unexpectedly ($error)');
86	    return left(Failure.malformedResponse(message: error.toString()));
87	  }
88	
89	  @override
90	  Widget build(BuildContext context) {
91	    return MaterialApp.router(
92	      debugShowCheckedModeBanner: false,
93	      routerConfig: _router,
94	      builder: (context, child) => ExpiryOverlayHost(
95	        sessionRepository: _sessionRepository,
96	        router: _router,
97	        child: child!,
98	      ),
99	    );
100	  }
101	}
