42	void main() {
43	  setUp(() {
44	    ConfirmationDialog.isOpen = false;
45	  });
46	
47	  testWidgets('an expired emission before the Navigator behind navigatorKey is '
48	      'mounted finds no overlay context, does not throw, and resets its '
49	      'one-shot guard so a later mount can still show the overlay', (
50	    tester,
51	  ) async {
52	    final fakeSessionRepository = _FakeSessionRepository();
53	    addTearDown(fakeSessionRepository.dispose);
54	    final router = GoRouter(
55	      routes: [
56	        GoRoute(path: '/', builder: (context, state) => const SizedBox()),
57	      ],
58	    );
59	    addTearDown(router.dispose);
60	    final navigatorKey = GlobalKey<NavigatorState>();
61	
62	    // First mount: `navigatorKey` matches nothing in this tree — no
63	    // `Navigator` anywhere uses it — simulating the Navigator not being
64	    // mounted yet when the expiry event arrives.
65	    await tester.pumpWidget(
66	      Directionality(
67	        textDirection: TextDirection.ltr,
68	        child: ExpiryOverlayHost(
69	          sessionRepository: fakeSessionRepository,
70	          router: router,
71	          navigatorKey: navigatorKey,
72	          child: const SizedBox(),
73	        ),
74	      ),
75	    );
76	
77	    fakeSessionRepository.setStatus(SessionStatus.expired);
78	    await tester.pumpAndSettle();
79	
80	    expect(tester.takeException(), isNull);
81	    expect(find.byType(ConfirmationDialog), findsNothing);
82	
83	    // Second pump of the *same* `ExpiryOverlayHost` (same type, no key,
84	    // same position — its State is preserved, not remounted): now the
85	    // child actually contains a `Navigator` using `navigatorKey`, so
86	    // `navigatorKey.currentState` resolves. Re-emitting `expired` here
87	    // only shows the overlay if the earlier failed attempt reset
88	    // `_expiryOverlayShown` back to `false` — if that guard had stayed
89	    // stuck `true`, this second, now-resolvable attempt would stay
90	    // silently dropped too.
91	    await tester.pumpWidget(
92	      Directionality(
93	        textDirection: TextDirection.ltr,
94	        child: ExpiryOverlayHost(
95	          sessionRepository: fakeSessionRepository,
96	          router: router,
97	          navigatorKey: navigatorKey,
98	          child: Navigator(
99	            key: navigatorKey,
100	            onGenerateRoute: (settings) =>
101	                MaterialPageRoute<void>(builder: (context) => const SizedBox()),
102	          ),
103	        ),
104	      ),
105	    );
106	
107	    fakeSessionRepository.setStatus(SessionStatus.expired);
108	    await tester.pumpAndSettle();
109	
110	    expect(tester.takeException(), isNull);
111	    expect(find.text('Sessão expirada'), findsOneWidget);
112	  });
